<?php

namespace App\Controller;

use ApiPlatform\OpenApi\Factory\OpenApiFactoryInterface;
use ApiPlatform\OpenApi\Serializer\OpenApiNormalizer;
use App\OpenApi\Documentation;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\Routing\Attribute\Route;
use Symfony\Component\Serializer\SerializerInterface;

/**
 * Serves the OpenAPI document generated by API Platform for every operation of the API, in OpenAPI 3.0.
 */
final class OpenApiController
{
    private const CONTEXT = ['spec_version' => '3.0.0'];

    public function __construct(
        private readonly OpenApiFactoryInterface $openApiFactory,
        private readonly SerializerInterface $serializer,
    ) {
    }

    #[Route('/openapi.json', name: 'openapi', methods: ['GET'])]
    public function __invoke(): Response
    {
        $openApi = $this->serializer->serialize(($this->openApiFactory)(self::CONTEXT), OpenApiNormalizer::JSON_FORMAT, self::CONTEXT);
        $document = Documentation::apply(json_decode($openApi, true, 512, \JSON_THROW_ON_ERROR));

        return new Response(json_encode($document, \JSON_THROW_ON_ERROR | \JSON_UNESCAPED_SLASHES), 200, ['Content-Type' => 'application/json']);
    }
}
